const iconBySlug = new Map(APP_ICONS.map((i) => [i.slug, i]));

/** Look up one icon by slug, e.g. icon("figma"). Throws if the slug is unknown. */
export function icon(slug: string): AppIcon {
  const found = iconBySlug.get(slug);
  if (!found) throw new Error(`Unknown app icon: "${slug}"`);
  return found;
}

/** Several icons in the order you name them: icons("figma", "slack", "notion") */
export function icons(...slugs: string[]): AppIcon[] {
  return slugs.map(icon);
}

/** Every icon in a category, e.g. iconsIn("ai") */
export function iconsIn(category: IconCategory): AppIcon[] {
  return APP_ICONS.filter((i) => i.category === category);
}

/** Every wallpaper in a category, e.g. wallpapersIn("cityscape") */
export function wallpapersIn(category: WallpaperCategory): Wallpaper[] {
  return WALLPAPERS.filter((w) => w.category === category);
}

/** One wallpaper by id (its filename without the extension). */
export function wallpaper(id: string): Wallpaper {
  const found = WALLPAPERS.find((w) => w.id === id);
  if (!found) throw new Error(`Unknown wallpaper: "${id}"`);
  return found;
}
